SELECT COUNT(*) AS item_count
FROM marts.dim_item
WHERE dept_id = 'FOODS_2';

SELECT item_id, launch_date
FROM marts.dim_item
WHERE item_id = 'FOODS_1_009';

SELECT event_name
FROM marts.dim_date
WHERE date = DATE '2014-07-04';

SELECT SUM(units_sold) AS units_sold_last_7_days
FROM marts.fct_daily_sales
WHERE date > (SELECT MAX(date) FROM marts.fct_daily_sales) - INTERVAL 7 DAY;

SELECT SUM(units_sold) AS total_units_sold
FROM marts.fct_daily_sales
WHERE date BETWEEN DATE '2014-12-18' AND DATE '2014-12-24';

SELECT AVG(item_avg_price) AS avg_item_price_usd
FROM (
    SELECT item_id, AVG(sell_price) AS item_avg_price
    FROM marts.fct_daily_sales
    GROUP BY item_id
) AS per_item;

SELECT SUM(units_sold) AS units_sold
FROM marts.fct_daily_sales
WHERE date = DATE '2015-05-10';

SELECT COUNT(*) AS item_count
FROM marts.dim_item
WHERE dept_id = 'FOODS_2';

